|---|---|---|---|---|---|---|---|---|---|---|
| 101 | D1 | CARMONAO | 08/08/2026 23:57 | Ready | Preplan | Call driver | Solo | Dallas | 3 | 9 |
| 202 | A2 |  | 12/31/26 23:59 | Clean\_QA | Unknown |  | Unknown | Yard | 8 | 1 |
'@
  $pre=Get-ImportPreview $pta 'pta.txt' auto;Assert ($pre.type-eq'pta'-and$pre.valid_rows-eq2) 'PTA Markdown parse and separator handling';$imp=Import-WaaData $pta 'pta.txt' auto;Assert ($imp.rows-eq2) 'PTA transactional import';$cur=@(Get-CurrentDrivers);Assert ($cur.Count-eq1-and$cur[0].pta_code-eq'CARMONAO') 'canonical driver and truck observation';$sent=Invoke-Sql "SELECT actionable,source_numeric_1,source_numeric_2 FROM pta_observations WHERE truck='202';" -Json;Assert ($sent[0].actionable-eq0-and$sent[0].source_numeric_1-eq'8') 'sentinel non-actionable and unknown numerics preserved';$pin=Invoke-Sql "SELECT count(*) c FROM pta_observations WHERE actionable=1 AND substr(pta_at,12,5)='23:57';" -Json;Assert ($pin[0].c-eq1) 'legitimate 23:57 retained actionable'
  $dupe=$false;try{Import-WaaData $pta 'again.txt' auto|Out-Null}catch{$dupe=$_.Exception.Message-like'Duplicate*'};Assert $dupe 'SHA-256 duplicate import blocked'
  $did=[int]$cur[0].id;Invoke-Sql "INSERT INTO idle_periods(driver_id,truck,period_start,period_end,engine_hours,idle_hours) VALUES($did,'101','2026-07-13','2026-07-19',20,2),($did,'101','2026-07-20','2026-07-26',40,7),($did,'101','2026-07-27','2026-08-02',10,8),($did,'101','2026-08-03','2026-08-09',30,3);" -AllowWrite|Out-Null;$dash=Get-Dashboard;$row=@($dash.drivers|Where-Object{$_.id-eq$did})[0];Assert ([double]$row.p7-eq10) 'latest idle percentage derived';Assert ([math]::Abs([double]$row.p28-20)-lt.01-and$row.coverage28-eq'Complete') '28-day percentage weighted, not averaged';Invoke-Sql "INSERT INTO drivers(full_name,pta_code) VALUES('Zero Driver','ZERODRIV');INSERT INTO idle_periods(driver_id,truck,period_start,period_end,engine_hours,idle_hours) VALUES(last_insert_rowid(),'0','2026-08-03','2026-08-09',0,0);" -AllowWrite|Out-Null;$zero=@((Get-Dashboard).drivers|Where-Object{$_.pta_code-eq'ZERODRIV'})[0];Assert ($null-eq$zero.p7-and$zero.coverage28-eq'Partial Data') 'zero engine hours is No Data and incomplete coverage is labeled'
  Invoke-Sql "INSERT INTO drivers(full_name,pta_code) VALUES('Exact Zero','EXACTZER');INSERT INTO idle_periods(driver_id,truck,period_start,period_end,engine_hours,idle_hours) VALUES(last_insert_rowid(),'ZERO','2026-07-13','2026-07-19',10,1),((SELECT id FROM drivers WHERE pta_code='EXACTZER'),'ZERO','2026-07-20','2026-07-26',10,1),((SELECT id FROM drivers WHERE pta_code='EXACTZER'),'ZERO','2026-07-27','2026-08-02',10,1),((SELECT id FROM drivers WHERE pta_code='EXACTZER'),'ZERO','2026-08-03','2026-08-09',10,0);INSERT INTO drivers(full_name,pta_code) VALUES('Exact Hundred','EXACTHUN');INSERT INTO idle_periods(driver_id,truck,period_start,period_end,engine_hours,idle_hours) VALUES(last_insert_rowid(),'HUNDRED','2026-07-13','2026-07-19',10,1),((SELECT id FROM drivers WHERE pta_code='EXACTHUN'),'HUNDRED','2026-07-20','2026-07-26',10,1),((SELECT id FROM drivers WHERE pta_code='EXACTHUN'),'HUNDRED','2026-07-27','2026-08-02',10,1),((SELECT id FROM drivers WHERE pta_code='EXACTHUN'),'HUNDRED','2026-08-03','2026-08-09',10,10);" -AllowWrite|Out-Null;$guarded=Get-Dashboard;Assert (@($guarded.heroes+$guarded.training|Where-Object{$_.pta_code-in@('EXACTZER','EXACTHUN')}).Count-eq0) 'exact 0% and 100% weekly values are excluded from both Top 5 rankings';$guardRows=@($guarded.drivers|Where-Object{$_.pta_code-in@('EXACTZER','EXACTHUN')});Assert ($guardRows.Count-eq2-and@($guardRows|Where-Object{$null-ne$_.p28}).Count-eq2) 'Top 5 weekly safeguard does not alter weighted 28-day values'
