  $card=Get-DriverCard $did;Save-DriverAction $did @{action='pta';value='08/10/2026 10:30'}|Out-Null;Assert ((Invoke-Sql "SELECT count(*) c FROM pta_observations WHERE driver_id=$did;" -Json)[0].c-eq2) 'manual PTA appends observation';Save-DriverAction $did @{action='note';text='Called driver'}|Out-Null;Save-DriverAction $did @{action='reminder';text='Check back';due_at='08/10/2026 12:00'}|Out-Null;Save-DriverAction $did @{action='timer';label='Thirty minutes';target_at='08/10/2026 11:00'}|Out-Null;$card=Get-DriverCard $did;Assert ($card.notes.Count-eq1-and$card.reminders.Count-eq1-and$card.timers.Count-eq1) 'notes reminders and timers persist'
  $conversation=Save-WaaConversation -DriverId $did -Body @{field='fuel_status';value='Good'};Invoke-WaaLiveCheckpoint -Force|Out-Null;Assert ($conversation.fuel_status-eq'Good'-and(Invoke-Sql "SELECT count(*) FROM audit_history WHERE entity_id='$did' AND action='call_flow_update';").Trim()-eq'1') 'conversation update returns its compact session and audits once';Save-WaaConversation -DriverId $did -Body @{field='eta_note';value='First ETA'}|Out-Null;Save-WaaConversation -DriverId $did -Body @{field='eta_note';value='Revised ETA'}|Out-Null;Invoke-WaaLiveCheckpoint -Force|Out-Null;$rapidEdits=Invoke-Sql "SELECT count(DISTINCT json_extract(detail_json,'$.value')) c FROM audit_history WHERE entity_id='$did' AND action='call_flow_update' AND json_extract(detail_json,'$.field')='eta_note';" -Json;Assert ($rapidEdits[0].c-eq2) 'rapid conversation edits retain their values so cleanup cannot merge distinct work';Save-WaaConversation -DriverId $did -Body @{field='completed_at';value=$true}|Out-Null;$completedDriver=@(Get-CurrentDrivers|Where-Object{$_.id-eq$did})[0];Assert ([int]$completedDriver.call_completed-eq1) 'finishing a call persists completion on the current driver cycle';Save-DriverAction $did @{action='pta';value='08/11/2026 10:30'}|Out-Null;$nextCycleDriver=@(Get-CurrentDrivers|Where-Object{$_.id-eq$did})[0];Assert ([int]$nextCycleDriver.call_completed-eq0) 'a new PTA cycle returns the driver to the pending workflow queue';Save-WaaConversation -DriverId $did -Body @{field='completed_at';value=$true}|Out-Null;$recompletedDriver=@(Get-CurrentDrivers|Where-Object{$_.id-eq$did})[0];Assert ([int]$recompletedDriver.call_completed-eq1) 'the new driver cycle can be completed independently';Invoke-WaaLiveCheckpoint -Force|Out-Null;Invoke-Sql "UPDATE driver_call_sessions SET cycle_key='101|08/11/2026' WHERE driver_id=$did AND cycle_key='101|2026-08-11';" -AllowWrite|Out-Null;Initialize-Waa $root $data -SkipStartupBackup|Out-Null;$migratedCycle=Invoke-Sql "SELECT cycle_key FROM driver_call_sessions WHERE driver_id=$did AND completed_at IS NOT NULL ORDER BY id DESC LIMIT 1;";Assert ($migratedCycle-eq'101|2026-08-11'-and[int](@(Get-CurrentDrivers|Where-Object{$_.id-eq$did})[0].call_completed)-eq1) 'legacy locale-formatted call cycles migrate without losing completion';$minimal=Save-DriverAction $did @{action='home_checked';value=$true};Assert ($minimal.ok-and-not$minimal.ContainsKey('driver')) 'ordinary driver mutations return a minimal response instead of the full work card'
