  Assert ((Invoke-Sql "SELECT count(*) c FROM sqlite_master WHERE type='index' AND name IN('idx_truck_driver_time','idx_notes_driver_created','idx_audit_time','idx_audit_review');" -Json)[0].c-eq4) 'driver and daily-review query indexes created'
  Invoke-Sql "INSERT INTO drivers(full_name,pta_code) VALUES('Unassigned Driver','UNASSIGD');" -AllowWrite|Out-Null;$unassigned=[int](Invoke-Sql 'SELECT max(id) FROM drivers;');Save-DriverAction $unassigned @{action='assign_truck';value=' trk-902 '}|Out-Null;$assigned=Get-CurrentDriver $unassigned;Assert ($assigned.truck-eq'TRK-902') 'manual assignment becomes the current truck for an unassigned driver';Assert ((Invoke-Sql "SELECT count(*) c FROM truck_history WHERE driver_id=$unassigned AND truck='TRK-902' AND source='manual';" -Json)[0].c-eq1) 'manual assignment is stored as truck history, not driver identity';Assert ((Invoke-Sql "SELECT count(*) c FROM audit_history WHERE entity_type='driver' AND entity_id='$unassigned' AND action='assign_truck';" -Json)[0].c-eq1) 'manual truck assignment is audited';Save-DriverAction $unassigned @{action='assign_truck';value='999'}|Out-Null;$reassigned=Get-CurrentDriver $unassigned;Assert ($reassigned.truck-eq'999'-and(Invoke-Sql "SELECT count(*) FROM truck_history WHERE driver_id=$unassigned AND source='manual';").Trim()-eq'2') 'any driver can be reassigned while prior truck history is preserved';$sameTruckBlocked=$false;try{Save-DriverAction $unassigned @{action='assign_truck';value='999'}|Out-Null}catch{$sameTruckBlocked=$_.Exception.Message-like'*already current*'};Assert $sameTruckBlocked 'reassigning the same current truck is rejected as a no-op'
  Save-DriverAction $did @{action='note';text='Delete this note'}|Out-Null;$deleteNote=[int](Invoke-Sql "SELECT max(id) FROM driver_notes WHERE driver_id=$did;");$wrongOwner=$false;try{Save-DriverAction $unassigned @{action='delete_note';item_id=$deleteNote}|Out-Null}catch{$wrongOwner=$_.Exception.Message-like'*not found*'};Assert $wrongOwner 'note deletion enforces driver ownership';Save-DriverAction $did @{action='delete_note';item_id=$deleteNote}|Out-Null;Assert ((Invoke-Sql "SELECT count(*) c FROM driver_notes WHERE id=$deleteNote;" -Json)[0].c-eq0) 'driver note can be manually deleted';$deleteReminder=[int](Invoke-Sql "SELECT max(id) FROM reminders WHERE driver_id=$did;");Save-DriverAction $did @{action='delete_reminder';item_id=$deleteReminder}|Out-Null;Assert ((Invoke-Sql "SELECT count(*) c FROM reminders WHERE id=$deleteReminder;" -Json)[0].c-eq0) 'driver reminder can be manually deleted';$deleteActivity=[int](Invoke-Sql "SELECT max(id) FROM audit_history WHERE entity_type='driver' AND entity_id='$did' AND action='delete_note';");Remove-DailyActivity $deleteActivity|Out-Null;Assert ((Invoke-Sql "SELECT count(*) c FROM audit_history WHERE id=$deleteActivity;" -Json)[0].c-eq0) 'Daily Review activity record can be manually deleted'
  Save-DriverAction $did @{action='reminder';text='Snooze me';due_at='08/10/2026 12:00'}|Out-Null;Invoke-WaaLiveCheckpoint -Force|Out-Null;$snoozeId=[int](Invoke-Sql "SELECT max(id) FROM reminders WHERE driver_id=$did;");$followups=Save-DriverAction $did @{action='snooze_reminder';item_id=$snoozeId;return_followups=$true};Assert ($followups.reminders.Count-eq1-and([datetime]$followups.reminders[0].due_at).Day-eq11) 'reminder snooze updates due time and returns only follow-up lists';$timerId=[int](Invoke-Sql "SELECT max(id) FROM timers WHERE driver_id=$did;");Save-DriverAction $did @{action='delete_timer';item_id=$timerId}|Out-Null;Assert ((Invoke-Sql "SELECT count(*) FROM timers WHERE id=$timerId;").Trim()-eq'0') 'driver timer can be manually deleted'
  Save-DriverAction $did @{action='include_transition';value=$true}|Out-Null;Save-DriverAction $did @{action='transition_note';value='Follow up'}|Out-Null;$tr=Get-Transition;Assert ($tr.body.StartsWith("No Open ACE/ACI's")-and$tr.body.Contains("101 - $($cur[0].full_name) : Follow up")) 'Send to Transition automatically appends the exact driver line to a generated draft';Save-Transition 'Manual text'|Out-Null;Save-DriverAction $did @{action='transition_note';value='Updated follow up'}|Out-Null;$manualTransition=Get-Transition;Assert ($manualTransition.is_manual-eq1-and$manualTransition.body.StartsWith('Manual text')-and$manualTransition.body.Contains("101 - $($cur[0].full_name) : Updated follow up")) 'driver transition changes update only their line without erasing manual draft text'
  $headers=@('Order','Empty Call Date','Origin','Destination')+@(5..27|ForEach-Object{"Field $_"})+@('Last Dispatch Driver cd','Last Dispatch Driver nm');$values=@('ORD-1','08/01/2026','Dallas','Tulsa')+@(5..27|ForEach-Object{"v$_"})+@('D100','Driver Example');$bol=($headers-join"`t")+"`r`n"+($values-join"`t");$bp=Get-ImportPreview $bol 'Order Details Missing BOL.csv' auto;Assert ($bp.type-eq'bol'-and$bp.valid_rows-eq1) 'UTF-16 content-shaped 29-column BOL parser';Import-WaaData $bol 'Order Details Missing BOL.csv' auto|Out-Null;Assert ((Invoke-Sql "SELECT count(*) c FROM missing_bols WHERE order_number='ORD-1';" -Json)[0].c-eq1) 'Missing BOL stored by driver evidence'
  $idleHeader=@('Group by  (copy)','Unit Code','Week Start Date','Rolling 7 Day Start Date','[Rolling 7 Day Engine Time]/60','[Rolling 7 Day Idle Time]/60','Measure Names')-join',';$idleRow=@('D200 Example Driver','777','08/09/2026','08/03/2026','50','5','Idle %')-join',';$idleRaw=$idleHeader+"`r`n"+$idleRow;Assert ((Get-ImportPreview $idleRaw 'rolling.csv' auto).type-eq'idle') 'rolling idle content detection';Import-WaaData $idleRaw 'rolling.csv' auto|Out-Null;Assert ((Invoke-Sql "SELECT round(idle_hours*100.0/engine_hours,1) p FROM idle_periods WHERE truck='777';" -Json)[0].p-eq10) 'rolling idle parser stores base hours'
  $historyDl=Join-Path $data 'HistoryDownloads';[IO.Directory]::CreateDirectory($historyDl)|Out-Null;$weeks=@(@('06/29/2026','07/05/2026',20,2),@('07/06/2026','07/12/2026',30,3),@('07/13/2026','07/19/2026',40,8),@('07/20/2026','07/26/2026',10,2));for($i=0;$i-lt4;$i++){$w=$weeks[$i];$file=Join-Path $historyDl "Rolling 7 Day history $i.csv";Set-Content $file ($idleHeader+"`r`n"+(@('D300 History Driver','888',$w[1],$w[0],$w[2],$w[3],'Idle %')-join','));(Get-Item $file).LastWriteTimeUtc=(Get-Date).ToUniversalTime().AddDays(-4+$i)};$invalidHistory=Join-Path $historyDl 'Rolling 7 Day invalid.csv';Set-Content $invalidHistory 'not a report';(Get-Item $invalidHistory).LastWriteTimeUtc=(Get-Date).ToUniversalTime().AddDays(-10);$historyScan=Invoke-WaaDownloadsScan -DownloadsPath $historyDl;$historyDriver=@((Get-Dashboard).drivers|Where-Object{$_.full_name-eq'History Driver'})[0];Assert ($historyScan.results.idle.imported_count-eq4-and$historyScan.results.idle.errors-eq1-and$historyDriver.coverage28-eq'Complete'-and[double]$historyDriver.p28-eq15) 'idle intake skips invalid history and backfills four weekly downloads into a weighted 28-day result';$idleBatchCount=(Invoke-Sql "SELECT count(*) FROM import_batches WHERE import_type='idle';").Trim();$repeatScan=Invoke-WaaDownloadsScan -DownloadsPath $historyDl;Assert (-not$repeatScan.results.idle.imported-and(Invoke-Sql "SELECT count(*) FROM import_batches WHERE import_type='idle';").Trim()-eq$idleBatchCount) 'unchanged idle history uses the lightweight candidate signature path'
