  $b=Backup-Waa 'test';Assert (Test-Path $b.path) 'SQLite-safe backup created';Invoke-Sql "INSERT INTO settings(key,value) VALUES('persistence','yes');" -AllowWrite|Out-Null;Initialize-Waa $root $data|Out-Null;Assert ((Invoke-Sql "SELECT value FROM settings WHERE key='persistence';").Trim()-eq'yes') 'clean restart and persistence';Assert ((Get-DataQuality).backups.Count-ge1) 'automatic backup visible'
  $traversal=[IO.Path]::GetFullPath((Join-Path (Join-Path $root 'web') '../AGENTS.md'));Assert (!$traversal.StartsWith([IO.Path]::GetFullPath((Join-Path $root 'web'))+[IO.Path]::DirectorySeparatorChar)) 'path traversal canonicalization rejects outside file';$dbSource=Get-Content (Join-Path $root 'src/Waa.psm1') -Raw;Assert ($dbSource.Contains('Start-WaaSqlSession')-and$dbSource.Contains('StandardInput.WriteLine($Sql)')-and$dbSource.Contains('Module.OnRemove')) 'database layer reuses and cleans up one persistent SQLite session';$serverSource=Get-Content (Join-Path $root 'src/Server.ps1') -Raw;Assert ($serverSource.Contains('[Net.IPAddress]::Loopback')) 'server binds loopback only';Assert ($serverSource.Contains('26214400')-and$serverSource.Contains('StaticCache')-and$serverSource.Contains('ReadTimeout')-and$serverSource.Contains('Revalidate')) 'HTTP limits, timeouts, revalidation, and static cache enabled';Assert ($serverSource-notmatch '\$startup(Intake|Identity)' -and $serverSource.Contains('Invoke-WaaDownloadsScan -DeferIdentityRepair') -and $serverSource.Contains('maintenance_status')) 'startup binds before versioned report and identity maintenance runs in the background';$webIndex=Get-Content (Join-Path $root 'web/index.html') -Raw;Assert ($webIndex-notmatch'https?://') 'web client has no Internet dependency';Assert ($webIndex.Contains('#organizer')-and$webIndex.Contains('#activity')-and$webIndex.Contains('#idle')) 'driver organizer, Idle Coaching, and daily-review tabs are integrated navigation';Assert ($webIndex.Contains('app.js?v=')-and$webIndex.Contains('styles.css?v=')) 'versioned assets prevent stale duplicate-listener client code after upgrades';$appSource=Get-Content (Join-Path $root 'web/app.js') -Raw;Assert ($appSource.Contains("chart(data.history28, { field: 'p28'")-and$appSource.Contains("invalidate('/api/dashboard', '/api/drivers'")) 'dashboard binds the 28-day field and invalidates cached data after imports';Assert ($appSource.Contains('monitorHealth')-and$appSource.Contains('LOOPBACK · SYNCING')-and$appSource.Contains('maintenanceWasRunning')) 'client refreshes cached operational views when background startup maintenance completes';Assert ($serverSource.Contains('/context')-and$appSource.Contains('/context')-and$serverSource-notmatch "GET'.+?/conversation") 'Driver Work Card uses one context read with no redundant conversation GET endpoint';Assert ($appSource.Contains('data-delete-timer')-and$appSource.Contains('data-snooze-reminder')-and$appSource.Contains("'ontime_status'")) 'timers snoozing and on-time fields are connected to the shared card';Assert ($appSource.Contains('quick-truck-form')) 'truck assignment is integrated into Workflow and Driver Work Card UI';Assert ($appSource.Contains('cardEventsController?.abort()')-and$appSource.Contains('listenerOptions')) 'Driver Work Card replaces old listener scope instead of accumulating duplicate saves';Assert ($appSource.Contains('data-organizer-delete')-and$appSource.Contains('data-delete-activity')) 'manual delete controls are integrated across organizer and Daily Review';Assert ($appSource.Contains('data-finish-call')-and$appSource.Contains('awaitPendingSaves')-and$appSource.Contains('cardLoadController?.abort()')) 'resumable step flow finishes calls, drains saves, and cancels stale card reads';Assert ($appSource.Contains('data-call-state')-and$appSource.Contains('Pending calls')-and$appSource.Contains('setCardQueue')-and$appSource.Contains('startQueue')) 'Workflow exposes persistent pending/completed queues and direct driver progression';Assert ($serverSource.Contains('/api/activity/cleanup')-and$appSource.Contains('cleanupActivity')) 'Daily Review exposes integrated bulk noise cleanup';Assert ($serverSource.Contains('/api/idle-coaching')-and$appSource.Contains('idleCoachingLog')) 'Idle Coaching tab is integrated through the normal server and client routing';Assert ($appSource.Contains('idleRowsByDriver: new Map()')-and$appSource.Contains('openIdleCoachingSummary')-and$appSource.Contains('data-review-idle-driver')-and$appSource.Contains('One coaching record per driver')-and -not $appSource.Contains('idle-log-entry open')) 'Idle Coaching groups every driver into one review card with all idle conversations';Assert ($appSource.Contains('data-review-driver')-and$appSource.Contains('activityRowsByDriver')-and$webIndex.Contains('activityModal')) 'Daily Review groups each day into one expandable summary per driver'
